/* From Uiverse.io by SanthoshSJ-Dev - Tags: simple, blue, button, bubble, plain */
.__UIV_SCOPE__ .button {
  appearance: none;
  background: transparent;
  border: 0;
  color: #fff;
  cursor: pointer;
  font: inherit;
  font-weight: 500;
  line-height: 1;
  padding: 1em 1.5em;
  position: relative;
  transition: filter 0.3s;
}

.__UIV_SCOPE__ .button:hover {
  filter: brightness(1.1);
}

.__UIV_SCOPE__ .button:active {
  filter: brightness(0.9);
}

.__UIV_SCOPE__ .button>span {
  display: block;
  position: relative;
  transition: transform 0.3s cubic-bezier(0.68, -0.6, 0.32, 1.6);
  z-index: 1;
}

.__UIV_SCOPE__ .button:hover>span {
  transform: scale(1.05);
}

.__UIV_SCOPE__ .button:active>span {
  transform: scale(0.95);
}

.__UIV_SCOPE__ .button>svg {
  fill: #0c2cde;
  position: absolute;
  top: -5%;
  left: -5%;
  width: 110%;
  height: 110%;
}

.__UIV_SCOPE__ .button>svg>path {
  transition: 0.3s cubic-bezier(0.68, -0.6, 0.32, 1.6);
}

.__UIV_SCOPE__ .button:hover>svg>path {
  d: path("M0,0 C0,-5 100,-5 100,0 C105,0 105,100 100,100 C100,105 0,105 0,100 C-5,100 -5,0 0,0");
}

.__UIV_SCOPE__ .button:active>svg>path {
  d: path("M0,0 C30,10 70,10 100,0 C95,30 95,70 100,100 C70,90 30,90 0,100 C5,70 5,30 0,0");
}
